use vstd::prelude::*;

verus! {

fn append(a: &Vec<i32>, b: i32) -> (out: Vec<i32>)
    ensures
        out@ == a@.push(b),
{
    let n: usize = a.len();
    let mut out: Vec<i32> = Vec::new();

    // Build `out` as a copy of `a`
    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            // `out` is exactly the prefix of `a` of length `i`
            out@ == a@.subrange(0, i as int),
        decreases n - i,
    {
        out.push(a[i]);
        i += 1;

        // Help the solver relate the updated vector to the subrange after extending by one element.
        assert(out@ == a@.subrange(0, i as int));
    }

    // Append the new value at the end
    out.push(b);

    // Now `out` equals the original sequence with `b` appended
    assert(out@ == a@.push(b)) by {
        // From the loop invariant at exit: out@ == a@.subrange(0, n) and n == a.len()
        // so subrange(0, n) is the whole sequence a@.
        assert(n == a@.len());
        assert(a@.subrange(0, n as int) == a@);
    }

    out
}

} // verus!

